
/* ===== BOTS ANIMADOS: FSB OPERATOR (esqueleto Mixamo) =====
   Modelo "FSB Operator" por Mateusz Woliński (CC BY 4.0, Sketchfab).
   Animações: parado (do próprio FSB), corrida (Mixamo "Running" do Frank, CC BY — passos e corrida tática),
   agachar e atirar ("hamass soldier" por abdallahemad800, CC BY 4.0, só o movimento). Tudo reprojetado para o esqueleto do FSB.
   Os bots vivos usam esse corpo; a caixa de acerto continua invisível (corpo + cabeça x2).
   Se o modelo não carregar ou der erro, o jogo usa os bots antigos. */
(function(){
'use strict';
let dead=false,TPL=null;
const GLB64='';
const SK=window.__SK={ready:0,n:0};
const fail=e=>{dead=true;SK.ready=0;try{console.error('[bots-fsb]',e)}catch(_){}};
const SRC=['https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/loaders/GLTFLoader.js','https://unpkg.com/three@0.128.0/examples/js/loaders/GLTFLoader.js','https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/examples/js/loaders/GLTFLoader.js'];
function load(i){return new Promise((res,rej)=>{if(typeof THREE!=='undefined'&&THREE.GLTFLoader)return res();if(i>=SRC.length)return rej(new Error('GLTFLoader indisponível'));const s=document.createElement('script');s.src=SRC[i];s.onload=()=>res();s.onerror=()=>{s.remove();load(i+1).then(res,rej)};document.head.appendChild(s)})}
const cl=(v,a,b)=>Math.max(a,Math.min(b,v));
const ss=(x,a,b)=>{const t=cl((x-a)/(b-a),0,1);return t*t*(3-2*t)};

/* copia o personagem (cada bot com o seu próprio esqueleto) */
function cloneSk(src){
 const A=[],B=[];src.traverse(o=>A.push(o));const c=src.clone(true);c.traverse(o=>B.push(o));
 const mp=new Map();A.forEach((o,i)=>mp.set(o,B[i]));
 A.forEach((o,i)=>{if(o.isSkinnedMesh){const n=B[i],sk=o.skeleton;
  n.bind(new THREE.Skeleton(sk.bones.map(b=>mp.get(b)),sk.boneInverses),n.matrixWorld)}});
 return c}

function build(team){
 const root=cloneSk(TPL.root);
 root.traverse(o=>{if(o.isMesh){o.raycast=function(){};o.frustumCulled=false;
  const nm=o.material&&o.material.name;
  if(nm==='uniform'||nm==='helmet'||nm==='gloves'||nm==='mask')o.material=TPL.mat[team][nm]||o.material}});
 return root}

function mkBotSK(team){
 const b={team,hp:0,p:new THREE.Vector3(),yaw:0,lt:0,cd:1,rs:Math.random()*1.5,tg:null,td:0,gt:0,sd:1,n:'FSB'};
 const g=new THREE.Group();g.rotation.order='YXZ';
 const vis=new THREE.Group();g.add(vis);
 const root=build(team);vis.add(root);
 /* caixas de acerto invisíveis */
 const hm=new THREE.MeshBasicMaterial({colorWrite:false,depthWrite:false,side:THREE.DoubleSide});
 const body=new THREE.Mesh(new THREE.BoxGeometry(.52,1.38,.4),hm);body.position.set(0,.72,0);body.userData.bot=b;g.add(body);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.17,10,8),hm);head.position.set(0,1.63,0);head.userData.bot=b;head.userData.head=1;g.add(head);
 const mx=new THREE.AnimationMixer(root),acts={};
 TPL.clips.forEach(c=>{const a=mx.clipAction(c,root);a.play();a.setEffectiveWeight(c.name==='idle'?1:0);a.time=Math.random()*c.duration;acts[c.name]=a});
 mx.update(.001);
 g.visible=false;S.add(g);b.mesh=g;
 /* peça falsa compatível com a física antiga (balanço, passos, queda) */
 const D=()=>new THREE.Group();
 b.rig={hip:[D(),D()],kp:[D(),D()],ft:[D(),D()],up:D(),lx:0,lz:0,sp:0,fs:0,ss:0,ph:Math.random()*6,si:0,fl:0,sk:1};
 b._sk={mx,acts,vis,body,head,cr:0,tw:0,ct:1+Math.random()*2,cs:0,dead:0,dt:0,ts:1};
 SK.n++;return b}
window.mkBotSK=mkBotSK;

function stepBot(b,dt){
 const k=b._sk;if(!k||!b.mesh)return;
 if(!b.mesh.visible)return;
 const r=b.rig||{},alive=b.hp>0;
 if(!alive){
  if(!k.dead){k.dead=1;k.dt=0}
  k.dt+=dt;if(k.dt<.9){const f=cl(dt*10,0,1);const a=k.acts;
   a.idle.setEffectiveWeight(a.idle.getEffectiveWeight()+(1-a.idle.getEffectiveWeight())*f);
   a.run.setEffectiveWeight(a.run.getEffectiveWeight()*(1-f));a.crouch.setEffectiveWeight(a.crouch.getEffectiveWeight()*(1-f));
   k.mx.update(dt*.3)}
  return}
 if(k.dead){k.dead=0;k.cr=0;k.tw=0;k.vis.rotation.y=0}
 const v=r.sp||0,fs=r.fs||0,sd=r.ss||0,eng=!!(b.tg&&b.tg.hp>0);
 /* agachar durante o tiroteio (só parado) */
 k.ct-=dt;
 if(k.ct<=0){
  if(k.cs){k.cs=0;k.ct=1+Math.random()*2.5}
  else if(eng&&b.td>7&&v<1.2&&Math.random()<.5){k.cs=1;k.ct=1.4+Math.random()*2}
  else k.ct=.8+Math.random()}
 if(v>1.6)k.cs=0;
 k.cr+=((k.cs?1:0)-k.cr)*cl(dt*6,0,1);
 /* corpo vira para o lado em que anda (limitado); de costas = corrida ao contrário */
 let tw=0,dir=1;
 if(v>.8){let ph=Math.atan2(sd,fs);if(Math.abs(ph)>Math.PI/2){ph-=Math.sign(ph)*Math.PI;dir=-1}tw=cl(ph*.7,-1,1)}
 k.tw+=(tw-k.tw)*cl(dt*8,0,1);k.vis.rotation.y=k.tw;
 const a=k.acts,mv=ss(v,.35,1.3)*(1-k.cr),wc=k.cr,wi=Math.max(0,1-mv-wc);
 a.idle.setEffectiveWeight(wi);a.run.setEffectiveWeight(mv);a.crouch.setEffectiveWeight(wc);
 a.run.setEffectiveTimeScale(dir*cl(v/TPL.runSpeed,.45,1.4));
 /* caixas de acerto acompanham o agachar */
 const s=1-.38*k.cr;k.body.scale.y=s;k.body.position.y=.03+.69*s;k.head.position.y=1.63-.55*k.cr;
 k.mx.update(dt)}

let lt=performance.now();
function tick(){
 const now=performance.now();let dt=(now-lt)/1000;lt=now;if(!(dt>0)||dt>.1)dt=.016;
 if(typeof started==='undefined'||!started)return;
 for(const b of bots)if(b._sk)stepBot(b,dt)}

function start(){
 try{
  if(typeof THREE==='undefined'||!THREE.GLTFLoader||typeof S==='undefined'||typeof bots==='undefined'||typeof ents==='undefined'||typeof P==='undefined'||typeof R==='undefined'||typeof C==='undefined'||typeof LB==='undefined'||typeof setupMatch!=='function')throw new Error('faltam peças do jogo');
  const bin=atob(GLB64),u8=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u8[i]=bin.charCodeAt(i);
  const cib0=window.createImageBitmap;window.createImageBitmap=undefined;
  try{new THREE.GLTFLoader().parse(u8.buffer,'',gltf=>{
   try{
    const root=gltf.scene,clips=gltf.animations||[];if(!root||clips.length<3)throw new Error('modelo sem animações');
    const mats={};
    root.traverse(o=>{if(o.isMesh){o.castShadow=/uniform|helmet/i.test(o.name);o.receiveShadow=false;
     [].concat(o.material).forEach(m=>{if(!m)return;if(m.map){m.map.encoding=THREE.LinearEncoding;m.map.anisotropy=2;m.map.needsUpdate=true}
      if(m.isMeshStandardMaterial){m.envMapIntensity=.5;m.metalness=Math.min(m.metalness,.2)}
      if(m.name==='eyes'){m.depthWrite=false}
      mats[m.name]=m;m.needsUpdate=true})}});
    const tint=[[0x86b4ff,0xc8dcff,0xffffff],[0xff8574,0xffc0b8,0xffffff]],tm=[{},{}];
    for(let t=0;t<2;t++){['uniform','helmet'].forEach((n,i)=>{const m=mats[n];if(!m)return;const c=m.clone();c.color.setHex(tint[t][i]);tm[t][n]=c})}
    const ex=(gltf.parser&&gltf.parser.json&&gltf.parser.json.extras)||{};
    TPL={root,clips,mat:tm,runSpeed:ex.runSpeed||3.7};
    root.updateMatrixWorld(true);
    /* troca o montador de partida: bots com o corpo novo */
    const osm=window.setupMatch;
    window.setupMatch=function(){
     if(dead||!TPL)return osm.apply(this,arguments);
     try{
      bots.forEach(b=>{try{S.remove(b.mesh)}catch(e){}});bots.length=0;P.team=LB.team;
      const nb=[0,1,5,6],nr=[2,3,4,7];(P.team?nb:nr).push(8);
      nb.forEach(()=>bots.push(mkBotSK(0)));nr.forEach(()=>bots.push(mkBotSK(1)));
      ents.length=0;ents.push(P,...bots);score=[0,0];RD.n=0
     }catch(e){fail(e);bots.forEach(b=>{try{S.remove(b.mesh)}catch(_){}});bots.length=0;return osm.apply(this,arguments)}};
    const pr=R.render;
    R.render=function(s,c){
     if(!dead&&s===S&&c===C){try{tick()}catch(e){fail(e)}}
     return pr.apply(R,arguments)};
    SK.ready=1;console.log('[bots-fsb] ok')
   }catch(e){fail(e)}
  },err=>fail(err))}finally{window.createImageBitmap=cib0}
 }catch(e){fail(e)}
}
try{load(0).then(start,e=>fail(e))}catch(e){fail(e)}
})();

